// Template classes for the split-dex tests.  A test copies one of them and
// renames its types (dexpp.Model.rename_types) to get the class it needs, so
// one small DEX file gives every class shape the tests use.  The class Wide,
// with 10,000 native methods, is generated by make_templates.sh, which also
// rebuilds templates.dex from this file.

package fix;

/** A class with no members besides its constructor. */
class Plain {}

/** Renamed together with Child, Parent becomes any superclass. */
class Parent {}

class Child extends Parent {}

/** Renamed together with Caller, Target becomes any class that Caller calls. */
class Target {
    static void go() {}
}

class Caller {
    static void run() {
        Target.go();
    }
}
